diff --git a/src/quota.ts b/src/quota.ts
--- a/src/quota.ts
+++ b/src/quota.ts
@@ -1,2 +1,7 @@
 export type Quota = {remaining: number};
 export const hasCapacity = (quota: Quota): boolean => quota.remaining > 0;
+export const reserveCapacity = (quota: Quota): boolean => {
+    if (!hasCapacity(quota)) return false;
+    quota.remaining -= 1;
+    return true;
+};
diff --git a/src/submit.ts b/src/submit.ts
--- a/src/submit.ts
+++ b/src/submit.ts
@@ -1,2 +1,2 @@
-import {hasCapacity, type Quota} from "./quota";
-export const submit = (q: Quota) => hasCapacity(q);
+import {reserveCapacity, type Quota} from "./quota";
+export const submit = (q: Quota) => reserveCapacity(q);
